package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.jsoup.Connection;
import org.jsoup.Jsoup;
import org.jsoup.helper.HttpConnection;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Document;
import org.jsoup.parser.Tag;
import org.jsoup.select.Elements;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class FormElement_formData_TriageGen1Test {

    private Document doc;
    private FormElement form;

    @Before
    public void setUp() {
        doc = Document.create();
        form = doc.createElement("form");
        doc.body().appendChild(form);
    }

    @Test
    public void testFormData_EmptyForm() {
        List<Connection.KeyVal> data = form.formData();
        Assert.assertTrue(data.isEmpty());
    }

    @Test
    public void testFormData_NonSubmittableElement() {
        // Assuming a tag that is not form submittable (like a div)
        Element div = doc.createElement("div");
        div.attr("name", "test");
        form.appendChild(div);

        List<Connection.KeyVal> data = form.formData();
        Assert.assertTrue(data.isEmpty());
    }

    @Test
    public void testFormData_ElementWithoutName() {
        Element input = doc.createElement("input");
        input.attr("type", "text");
        // No name attribute
        form.appendChild(input);

        List<Connection.KeyVal> data = form.formData();
        Assert.assertTrue(data.isEmpty());
    }

    @Test
    public void testFormData_TextType() {
        Element input = doc.createElement("input");
        input.attr("type", "text");
        input.attr("name", "username");
        input.attr("value", "jdoe");
        form.appendChild(input);

        List<Connection.KeyVal> data = form.formData();
        Assert.assertEquals(1, data.size());
        Assert.assertEquals("username", data.get(0).getKey());
        Assert.assertEquals("jdoe", data.get(0).getValue());
    }

    @Test
    public void testFormData_SelectWithSelectedOption() {
        Element select = doc.createElement("select");
        select.attr("name", "color");

        Element opt1 = doc.createElement("option");
        opt1.attr("value", "red");
        opt1.text("Red");

        Element opt2 = doc.createElement("option");
        opt2.attr("value", "blue");
        opt2.attr("selected", "selected");
        opt2.text("Blue");

        select.appendChild(opt1);
        select.appendChild(opt2);
        form.appendChild(select);

        List<Connection.KeyVal> data = form.formData();
        Assert.assertEquals(1, data.size());
        Assert.assertEquals("color", data.get(0).getKey());
        Assert.assertEquals("blue", data.get(0).getValue());
    }

    @Test
    public void testFormData_SelectWithMultipleSelectedOptions() {
        Element select = doc.createElement("select");
        select.attr("name", "colors");

        Element opt1 = doc.createElement("option");
        opt1.attr("value", "red");
        opt1.attr("selected", "selected");

        Element opt2 = doc.createElement("option");
        opt2.attr("value", "blue");
        opt2.attr("selected", "selected");

        select.appendChild(opt1);
        select.appendChild(opt2);
        form.appendChild(select);

        List<Connection.KeyVal> data = form.formData();
        Assert.assertEquals(2, data.size());
        Assert.assertEquals("red", data.get(0).getValue());
        Assert.assertEquals("blue", data.get(1).getValue());
    }

    @Test
    public void testFormData_SelectWithNoSelectedOption() {
        Element select = doc.createElement("select");
        select.attr("name", "fruit");

        Element opt1 = doc.createElement("option");
        opt1.attr("value", "apple");

        Element opt2 = doc.createElement("option");
        opt2.attr("value", "banana");

        select.appendChild(opt1);
        select.appendChild(opt2);
        form.appendChild(select);

        List<Connection.KeyVal> data = form.formData();
        Assert.assertEquals(1, data.size());
        Assert.assertEquals("apple", data.get(0).getValue());
    }

    @Test
    public void testFormData_SelectWithNoOptions() {
        Element select = doc.createElement("select");
        select.attr("name", "empty");
        form.appendChild(select);

        List<Connection.KeyVal> data = form.formData();
        Assert.assertTrue(data.isEmpty());
    }

    @Test
    public void testFormData_CheckboxChecked() {
        Element checkbox = doc.createElement("input");
        checkbox.attr("type", "checkbox");
        checkbox.attr("name", "agree");
        checkbox.attr("value", "yes");
        checkbox.attr("checked", "checked");
        form.appendChild(checkbox);

        List<Connection.KeyVal> data = form.formData();
        Assert.assertEquals(1, data.size());
        Assert.assertEquals("agree", data.get(0).getKey());
        Assert.assertEquals("yes", data.get(0).getValue());
    }

    @Test
    public void testFormData_CheckboxUnchecked() {
        Element checkbox = doc.createElement("input");
        checkbox.attr("type", "checkbox");
        checkbox.attr("name", "agree");
        checkbox.attr("value", "yes");
        form.appendChild(checkbox);

        List<Connection.KeyVal> data = form.formData();
        Assert.assertTrue(data.isEmpty());
    }

    @Test
    public void testFormData_RadioChecked() {
        Element radio = doc.createElement("input");
        radio.attr("type", "radio");
        radio.attr("name", "gender");
        radio.attr("value", "m");
        radio.attr("checked", "checked");
        form.appendChild(radio);

        List<Connection.KeyVal> data = form.formData();
        Assert.assertEquals(1, data.size());
        Assert.assertEquals("m", data.get(0).getValue());
    }

    @Test
    public void testFormData_RadioUnchecked() {
        Element radio = doc.createElement("input");
        radio.attr("type", "radio");
        radio.attr("name", "gender");
        radio.attr("value", "m");
        form.appendChild(radio);

        List<Connection.KeyVal> data = form.formData();
        Assert.assertTrue(data.isEmpty());
    }

    @Test
    public void testFormData_MixedElements() {
        // Text
        Element input1 = doc.createElement("input");
        input1.attr("type", "text");
        input1.attr("name", "txt");
        input1.attr("value", "val1");
        form.appendChild(input1);

        // Radio checked
        Element radio1 = doc.createElement("input");
        radio1.attr("type", "radio");
        radio1.attr("name", "rad");
        radio1.attr("value", "val2");
        radio1.attr("checked", "checked");
        form.appendChild(radio1);

        // Select
        Element select = doc.createElement("select");
        select.attr("name", "sel");
        Element opt = doc.createElement("option");
        opt.attr("value", "val3");
        select.appendChild(opt);
        form.appendChild(select);

        List<Connection.KeyVal> data = form.formData();
        Assert.assertEquals(3, data.size());
        Assert.assertEquals("val1", data.get(0).getValue());
        Assert.assertEquals("val2", data.get(1).getValue());
        Assert.assertEquals("val3", data.get(2).getValue());
    }
}
